import { notFound } from 'next/navigation';

interface PageProps {
  params: Promise<{ username: string }>;
}

async function getPortfolioData(username: string) {
  const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8001/api/v1';
  try {
    const res = await fetch(`${apiUrl}/portfolio/${username}`, {
      next: { revalidate: 60 },
    });
    if (!res.ok) return null;
    return res.json();
  } catch {
    return null;
  }
}

export default async function PortfolioPage({ params }: PageProps) {
  const { username } = await params;
  const data = await getPortfolioData(username);

  if (!data) {
    notFound();
  }

  const { user, portfolio } = data;

  return (
    <div className="min-h-screen bg-white">
      <div className="max-w-4xl mx-auto px-6 py-12">
        {/* Profile header */}
        <div className="flex items-center gap-4 mb-10">
          <div className="w-16 h-16 rounded-full overflow-hidden bg-gray-200 flex-shrink-0">
            {user.image ? (
              <img
                src={user.image}
                alt={user.name || username}
                className="w-full h-full object-cover"
              />
            ) : (
              <div className="w-full h-full bg-gradient-to-br from-[#9F80DA] to-[#8A6BC5] flex items-center justify-center text-white text-2xl font-bold">
                {(user.name || username).charAt(0).toUpperCase()}
              </div>
            )}
          </div>
          <h1 className="text-2xl font-bold text-[#1a1a1a]">
            {portfolio.title || `${user.name || username}'s portfolio`}
          </h1>
        </div>

        <div className="flex gap-10">
          {/* Left sidebar - Bio */}
          {portfolio.bio && (
            <div className="w-44 flex-shrink-0">
              <h2 className="font-bold text-[#1a1a1a] mb-3">Bio</h2>
              <p className="text-sm text-gray-600 leading-relaxed whitespace-pre-wrap">
                {portfolio.bio}
              </p>
            </div>
          )}

          {/* Course grid */}
          <div className="flex-1">
            {portfolio.courses.length === 0 ? (
              <div className="text-center py-20 text-gray-400">
                <p>No courses in this portfolio yet.</p>
              </div>
            ) : (
              <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                {portfolio.courses.map((course: any) => (
                  <div key={course.id} className="group cursor-pointer">
                    <div className="aspect-video rounded-2xl bg-gradient-to-br from-[#9F80DA]/20 to-[#8A6BC5]/20 flex items-center justify-center mb-3 group-hover:from-[#9F80DA]/30 group-hover:to-[#8A6BC5]/30 transition-colors">
                      <svg className="w-12 h-12 text-[#9F80DA]/50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                      </svg>
                    </div>
                    <p className="text-sm font-medium text-[#1a1a1a] text-center">
                      {course.title || 'Untitled Course'}
                    </p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export async function generateMetadata({ params }: PageProps) {
  const { username } = await params;
  const data = await getPortfolioData(username);

  if (!data) {
    return { title: 'Portfolio not found' };
  }

  return {
    title:
      data.portfolio.title ||
      `${data.user.name || username}'s Portfolio | acadion.ai`,
    description:
      data.portfolio.bio ||
      `View ${data.user.name || username}'s course portfolio on acadion.ai`,
  };
}
